SELECT p.version_code AS protocol_version, f.version_code AS feature_schema_version
FROM sim_protocol_version p JOIN sim_feature_schema_version f ON f.id = p.feature_schema_version_id
WHERE p.id = #{id}

SELECT EXISTS(SELECT 1  JOIN sim_user u ON u.id = #{actor}
    WHERE c.id = #{caseId} AND  AND u.status = 'ACTIVE'
    AND u.email_verified_at IS NOT NULL AND )

SELECT EXISTS(SELECT 1 FROM sim_audit_event a JOIN sim_assessment_case c ON c.id = #{caseId}
    WHERE a.actor_user_id = #{actor} AND a.action = 'HR_CASE_RESULTS_READ'
    AND a.resource_type = 'CASE' AND a.resource_ref_hash = SHA2(c.public_id, 256))

SELECT h.*, c.public_id AS case_public_id, v.title_snapshot AS job_title
 WHERE 
ORDER BY h.created_at DESC, h.id DESC LIMIT #{size} OFFSET #{offset}
